import{_ as e,c as o,b as a,a0 as r}from"./chunks/framework.DZ_FiXNr.js";const s="/images/show_optimization.webp",w=JSON.parse('{"title":"Show optimization","description":"Improve the title, author, description, and cover for your whole podcast. Use this page to check how well your show metadata matches your show keywords, then apply useful changes in your podcast host.","frontmatter":{},"headers":[],"relativePath":"features/show-optimization.md","filePath":"features/show-optimization.md"}'),i={name:"features/show-optimization.md"};function n(h,t,d,l,p,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="show-optimization" tabindex="-1">Show optimization <a class="header-anchor" href="#show-optimization" aria-label="Permalink to &quot;Show optimization&quot;">​</a></h1><p>Improve the title, author, description, and cover for your <strong>whole podcast</strong>. Use this page to check how well your show metadata matches your show keywords, then apply useful changes in your podcast host.</p><p><strong>To access:</strong> <strong>Command Center → Show optimization</strong>. Episode titles, descriptions, and covers are in <a href="/features/planner.html">Planner</a>.</p><p><a href="/images/show_optimization.webp" title="Open screenshot at full size"><img src="'+s+'" alt="Show optimization with show metadata scores and keyword rankings"></a></p><h2 id="check-your-show-keywords-first" tabindex="-1">Check your show keywords first <a class="header-anchor" href="#check-your-show-keywords-first" aria-label="Permalink to &quot;Check your show keywords first&quot;">​</a></h2><p>Open <a href="/features/keyword-strategy.html">Search Visibility → Strategy</a> and assign relevant terms to <strong>Show</strong>. These phrases guide title and author alignment. Description alignment and suggestions also consider your Unassigned keywords. Keywords assigned only to an episode, your brand, a guest, or a competitor do not become show targets.</p><p>Start with two or three relevant show keywords. The on-screen guidance helps you build a focused strategy; it is not a separate keyword allowance.</p><h2 id="read-the-alignment-card" tabindex="-1">Read the alignment card <a class="header-anchor" href="#read-the-alignment-card" aria-label="Permalink to &quot;Read the alignment card&quot;">​</a></h2><p><strong>Metadata / Keyword Alignment</strong> checks your <strong>Title</strong> and <strong>Author</strong> against show keywords. <strong>Description</strong> alignment also considers Unassigned keywords. Review the explanations alongside the scores to see what is missing. Cover analysis, when available, is shown with the artwork.</p><p>The adjacent <strong>Show keywords rankings</strong> table shows how your show ranks for those phrases across the listening platforms. Use <strong>Edit strategy</strong> to change your targets or <strong>View all tracked</strong> to inspect your tracked terms.</p><p>A good alignment score means your metadata represents your targets. It does not guarantee a search position, downloads, or a larger audience.</p><h2 id="get-suggestions-and-apply-changes" tabindex="-1">Get suggestions and apply changes <a class="header-anchor" href="#get-suggestions-and-apply-changes" aria-label="Permalink to &quot;Get suggestions and apply changes&quot;">​</a></h2><ol><li>Review your current show keywords and metadata.</li><li>On a paid plan, click <strong>Get AI suggestions for your podcast</strong>.</li><li>Review the proposed changes and keep the wording that accurately describes your show.</li><li>Copy your chosen title, author, or description into your podcast host and save it there.</li><li>After the updated information reaches the listening platforms, check your rankings in <a href="/features/keyword-tracker.html">Tracker</a>.</li></ol><p>Saving a suggestion or editing a draft in PodSEO does not rewrite your live feed. Apply live metadata changes through your host. If the page gives you a description task, open it for the exact phrase and verification steps.</p><h2 id="show-optimization-or-planner" tabindex="-1">Show optimization or Planner? <a class="header-anchor" href="#show-optimization-or-planner" aria-label="Permalink to &quot;Show optimization or Planner?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you want to improve</th><th>Where to work</th></tr></thead><tbody><tr><td>The podcast&#39;s title, author, description, or show cover</td><td><strong>Command Center → Show optimization</strong></td></tr><tr><td>One episode&#39;s title, description, keywords, or cover</td><td><strong>Command Center → Planner</strong>, then open the episode</td></tr><tr><td>Which phrases the show or an episode should target</td><td><strong>Search Visibility → Strategy</strong></td></tr><tr><td>Whether a change improved a tracked search position</td><td><strong>Search Visibility → Tracker</strong></td></tr></tbody></table><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>Show-keyword alignment covers the title, author, and description. AI metadata suggestions and the paid analysis features require a paid plan. Your plan&#39;s keyword allowance still applies.</p><p>For the complete sequence from positioning to measuring results, follow <a href="/getting-started/workflow.html">the PodSEO workflow</a>.</p>',19)])])}const u=e(i,[["render",n]]);export{w as __pageData,u as default};
